  input [2:0] sel,
  input [3:0] data0,
  input [3:0] data1,
  input [3:0] data2,
  input [3:0] data3,
  input [3:0] data4,
  input [3:0] data5,
  output [3:0] out,
  output parity
);

  wire [3:0] mux_out [0:5];
  wire [2:0] sel_dec [0:7];

