module decoder(
    input [7:0] in,
    output reg [7:0] out
);
    always @ (in) begin
        case (in)
            8'b00000001: out = 8'b00000001;
            8'b00000010: out = 8'b00000010;
            8'b00000100: out = 8'b00000100;
            8'b00001000: out = 8'b00001000;
            8'b00010000: out = 8'b00010000;
            8'b00100000: out = 8'b00100000;
