module mux2(
    input in0,
    input in1,
    input sel,
    output reg [1:0] out
);
    always @ (in0, in1, sel) begin
        case (sel)
            1'b0: out = {in1, in1};
            1'b1: out = {in0, in0};
            default: out = {in0, in0};
        endcase
    end
endmodule
