    input clk,
    input reset,
    input [7:0] d,
    output [7:0] q
);

    // Define internal signals
    wire [3:0] counter_out;
    wire [7:0] q_ff;
    wire select;
    wire [7:0] select_out;

    // Instantiate the binary counter module
