module binary_counter (
    input clk,
    input reset,
    output reg [3:0] count_out
);

    always @(posedge clk) begin
        if (reset) begin
            count_out <= 4'b0000;
        end else begin
            count_out <= count_out + 1;
        end
    end

endmodule
module flip_flop (
    input clk,
    input [7:0] d,
    output reg [7:0] q
);

    always @(posedge clk) begin
        q <= d;
    end

endmodule
module mux2to1 (
    input sel,
    input [7:0] in0,
    input [7:0] in1,
    output reg [7:0] out
);

    always @(sel, in0, in1) begin
        if (sel) begin
            out <= in1;
        end else begin
            out <= in0;
        end
    end

endmodule
