module RCB_FRL_count_to_128(clk, rst, count, ud, counter_value);

input clk, rst, count, ud;
output [6:0] counter_value;

wire [6:0] counter_value_preserver;
reg [6:0] counter_value;

always@(posedge clk or posedge rst)
begin
if(rst == 1'b1)
